-- Wave 10 fixer: replacement foods for corrected defaults. Generated by scripts/nutrition/corrections/add_foods.py from the
-- FoodData Central API (CC0). IDEMPOTENT. Run after seed-nutrition-zz-integration.sql and BEFORE seed-nutrition-zzz-corrections.sql.
begin;
insert into usda_foods (fdc_id, description, data_type, brand_owner, brand_name, serving_size, serving_size_unit, household_serving, publication_date)
values
  (2305175, 'DRY-CURED BRESAOLA', 'branded', 'Food Markets Northwest, Inc.', 'METROPOLITAN MARKET', 28.0, 'g', '3 Slices', '2022-04-09')
on conflict (fdc_id) do nothing;
insert into usda_food_nutrients (fdc_id, nutrient_id, amount_per_100g)
select v.fdc_id, n.id, e.value::numeric
from (values
  (2305175, '{"1008": 179.0, "2000": 0.0, "1162": 4.3, "1079": 0.0, "1253": 71.0, "1089": 2.57, "1004": 3.57, "1087": 0.0, "1258": 0.71, "1292": 0.0, "1293": 0.0, "1003": 35.71, "1257": 0.0, "1093": 1643.0, "1005": 0.0}'::jsonb)
) v(fdc_id, j) cross join lateral jsonb_each_text(v.j) e
join nutrients n on n.fdc_nutrient_id = e.key::int
on conflict (fdc_id, nutrient_id) do nothing;
commit;
